/**
 * Backend configuration, read once from environment variables (12-factor).
 *
 * Security mode:
 *   secure (default when ./secrets exists) - MQTT over TLS with credentials,
 *          signed device messages REQUIRED, dashboard login REQUIRED.
 *   dev    - plain MQTT, anonymous, unsigned messages accepted, no login.
 *
 * secrets/backend.env (generated by `npm run setup -w @twin/security`) is
 * loaded automatically; variables already set in the environment win.
 * File paths that do not exist (e.g. container paths when running locally)
 * fall back to the same file name inside ./secrets.
 */
import { existsSync } from 'node:fs';
import { basename, resolve } from 'node:path';

const REPO = resolve(import.meta.dirname, '../../..');
const SECRETS = process.env.SECRETS_DIR ?? resolve(REPO, 'secrets');
const envFile = resolve(SECRETS, 'backend.env');
if (existsSync(envFile)) process.loadEnvFile(envFile);

const env = process.env;
const num = (v: string | undefined, d: number) => (v === undefined || v === '' ? d : Number(v));
/** Resolve a secret file path, falling back to ./secrets/<name>. */
const secretFile = (p: string | undefined, name: string): string | undefined => {
  if (p && existsSync(p)) return p;
  const local = resolve(SECRETS, p ? basename(p) : name);
  return existsSync(local) ? local : undefined;
};

const securityMode = (env.SECURITY_MODE ?? (existsSync(resolve(SECRETS, 'ca.crt')) ? 'secure' : 'dev')) as 'secure' | 'dev';
const secure = securityMode === 'secure';
const mqttHost = env.MQTT_HOST ?? 'localhost';

export const config = {
  securityMode,
  secure,
  mqtt: {
    url: env.MQTT_URL ?? (secure ? `mqtts://${mqttHost}:8883` : `mqtt://${mqttHost}:1883`),
    username: env.MQTT_USERNAME || undefined,
    password: env.MQTT_PASSWORD || undefined,
    caFile: secure ? secretFile(env.MQTT_CA_FILE, 'ca.crt') : undefined,
    // Mosquitto forces client id = username in secure mode.
    clientId: env.MQTT_CLIENT_ID ?? (secure ? (env.MQTT_USERNAME ?? 'backend') : `twin-backend-${process.pid}`),
  },
  db: {
    host: env.POSTGRES_HOST ?? 'localhost',
    port: num(env.POSTGRES_PORT, 5432),
    user: env.POSTGRES_USER ?? 'twin',
    password: env.POSTGRES_PASSWORD ?? 'change-me-dev-only',
    database: env.POSTGRES_DB ?? 'pipeline_twin',
  },
  api: {
    host: env.API_HOST ?? '127.0.0.1',
    port: num(env.API_PORT, 4000),
    corsOrigin: env.CORS_ORIGIN ?? 'http://localhost:5173',
  },
  security: {
    deviceKeysFile: secretFile(env.DEVICE_KEYS_FILE, 'device-keys.json'),
    initialUsersFile: secretFile(env.INITIAL_USERS_FILE, 'initial-users.json'),
    /** Signed device messages mandatory (secure mode). */
    requireSignatures: secure,
    /** Dashboard login mandatory (secure mode). */
    requireLogin: secure,
    jwtSecret: env.JWT_SECRET ?? 'dev-only-insecure-jwt-secret-change-me',
    /** Accepted |platform clock - device clock| (ms). */
    maxClockSkewMs: num(env.MAX_CLOCK_SKEW_MS, 30_000),
    /** Messages per second per device above which traffic is dropped. */
    maxRatePerDevice: num(env.MAX_RATE_PER_DEVICE, 20),
  },
  ingestion: {
    flushMs: num(env.INGEST_FLUSH_MS, 1000),
    maxBatch: num(env.INGEST_MAX_BATCH, 200),
  },
  logLevel: env.LOG_LEVEL ?? 'info',
};
export type Config = typeof config;
